"""JSON API for the browser UI: dispatch(name, args_json) -> (status, json_text).

The page keeps the save ({seed, cash, actions}) in browser storage and sends it with `load` on start.
Nothing here returns data from after the current open (no peeking).
"""
import json
import math

import numpy as np

from . import cal, game, market, pricing

RUN = None


def _need():
    if RUN is None:
        raise game.TradeError("No run loaded.")
    return RUN


def _f(x, n=2):
    x = float(x)
    return None if math.isnan(x) else round(x, n)


# ---------------------------------------------------------------- lifecycle
def api_new(cash, seed, drift="market"):
    global RUN
    RUN = game.Run(int(seed), float(cash), drift=drift)
    return api_state()


def api_load(save):
    global RUN
    # saves from before drift choices existed (no "drift") replay on the original market
    RUN = game.Run(int(save["seed"]), float(save["cash"]), save.get("actions", []), drift=save.get("drift", "history"))
    return api_state()


def api_save():
    r = _need()
    return {"seed": r.seed, "cash": r.cash0, "drift": r.drift, "actions": r.actions, "version": 2}


def api_drifts():
    return [{"id": k, "label": v["label"], "target": v["target"]} for k, v in market.DRIFTS.items()]


def api_act(action):
    r = _need()
    before = len(r.events)
    r.apply(action)
    st = api_state()
    st["new_events"] = [_ev(e) for e in r.events[before:]]
    return st


# ---------------------------------------------------------------- views
def api_state():
    r = _need()
    S = r.spot()
    t = r.t
    prev_close = float(r.m["close"][t - 1]) if t else S
    pos = []
    for p in sorted(r.positions.values(), key=lambda p: (p["expiry"], p["strike"])):
        q = r.quote(p["type"], p["strike"], p["expiry"])
        mark = q["mid"]
        dist = (S / p["strike"] - 1) if p["type"] == "put" else (p["strike"] / S - 1)
        pos.append({"id": p["id"], "label": p["label"], "type": p["type"], "strike": p["strike"], "expiry": p["expiry"],
                    "qty": p["qty"], "open_px": p["open_px"], "mark": mark, "ask": q["ask"],
                    "pl": (p["open_px"] - mark) * 100 * p["qty"], "days": q["days"], "dist": dist,
                    "itm": dist < 0, "collateral": p["collateral"], "note": p["note"], "tags": p["tags"],
                    "opened": cal.label(p["open_t"], True)})
    snaps = r.snaps
    alerts = []
    for p in pos:
        if p["expiry"] == cal.friday(t):
            alerts.append(f"{p['label']} expires this Friday")
        if p["type"] == "put" and p["dist"] < 0.03:
            alerts.append(f"{p['label']} is {'in the money' if p['dist'] < 0 else 'within 3% of the strike'}")
    return {
        "t": t, "label": cal.label(t), "short": cal.label(t, True), "wday": t % 5,
        "spot": S, "prev_close": prev_close, "gap": S / prev_close - 1 if t else 0.0,
        "avail": r.avail, "collateral": r.collateral, "shares": r.shares(), "free_shares": r.free_shares(),
        "value": r.value(), "cash0": r.cash0, "accrued": r.accrued, "interest": r.interest_paid, "premium": r.premium,
        "rate": float(r.m["rate"][max(t - 1, 0)]),
        "vix": _f(r.m["vix"][t - 1]) if t else None, "fg": _f(r.m["fg"][t - 1], 0) if t else None,
        "stoch_k": _f(r.m["stoch_k"][t - 1], 0) if t else None,
        "lots": [{"qty": l["qty"], "cost": l["cost"], "how": l["how"], "since": cal.label(l["t"], True)} for l in r.lots],
        "positions": pos, "alerts": alerts,
        "bh": r.bh_shares * S, "cash_bench": r.cash_bench,
        "ret": r.value() / r.cash0 - 1, "weeks": t // 5,
        "drift": r.drift, "drift_label": market.DRIFTS[r.drift]["label"],
        "ended": r.ended, "seed": r.seed if r.ended else None, "eras": r.eras() if r.ended else None,
        "split_today": bool(r.m["split"][t]),
        "exps": [{"d": d, "label": cal.exp_label(d), "days": r.days_left(d), "monthly": cal.is_monthly(d)} for d in cal.expirations(t)],
    }


def api_chain(expiry):
    r = _need()
    S, exp = r.spot(), int(expiry)
    held = {(p["type"], p["strike"]) for p in r.positions.values() if p["expiry"] == exp}
    rows = []
    for K in pricing.list_strikes(S):
        if not (S * 0.6 <= K <= S * 1.4):
            continue
        c, p = r.quote("call", K, exp), r.quote("put", K, exp)
        rows.append({"k": K, "cb": c["bid"], "ca": c["ask"], "civ": c["iv"], "cd": c["delta"],
                     "pb": p["bid"], "pa": p["ask"], "piv": p["iv"], "pd": p["delta"],
                     "held_c": ("call", K) in held, "held_p": ("put", K) in held})
    return {"spot": S, "expiry": exp, "label": cal.exp_label(exp), "days": r.days_left(exp), "rows": rows,
            "atm_iv": r.atm_iv(r.days_left(exp))}


def api_preview(to="day"):
    """What an advance will do, using only what's known now (no future prices)."""
    r = _need()
    t, target = r.t, r.target(to)
    S = r.spot()
    settling = []
    for p in sorted(r.positions.values(), key=lambda p: p["expiry"]):
        if t <= p["expiry"] < target:
            put = p["type"] == "put"
            itm = (S < p["strike"]) if put else (S > p["strike"])
            q = p["qty"] * 100
            if put:
                then = f"if SimQ closes below {p['strike']:g}: you buy {q} shares for {game.money(p['strike'] * q)}"
                else_ = f"otherwise {game.money(p['collateral'])} collateral is released"
            else:
                then = f"if SimQ closes above {p['strike']:g}: your {q} shares are sold at {p['strike']:g}"
                else_ = "otherwise the shares are unlocked"
            settling.append({"label": p["label"], "when": cal.label(p["expiry"], True), "itm": itm,
                             "dist": (S / p["strike"] - 1) if put else (p["strike"] / S - 1), "then": then, "else": else_})
    fridays = [d for d in range(t, target) if d % 5 == 4]
    meetings = [d for d in range(t, target) if r.m["meeting"][d]]
    return {"to": to, "target": target, "label": cal.label(target), "days": target - t,
            "settling": settling, "itm_count": sum(1 for x in settling if x["itm"]),
            "interest_days": len(fridays), "accrued": r.accrued, "meeting": bool(meetings),
            "open_positions": len(r.positions)}


def _flags(r, order, chk):
    """Things worth a second look before confirming (they add a short pause, they never block)."""
    f = []
    e = chk.get("effects", {})
    act, S, val = order.get("action"), r.spot(), r.value()
    if act == "sell_to_open":
        K = float(order["strike"])
        if order["type"] == "put":
            if e.get("collateral", 0) > 0.5 * val:
                f.append(f"This put ties up {e['collateral'] / val:.0%} of your account.")
            if K > S:
                f.append(f"This put is already in the money (strike {K:g} above SimQ {S:.2f}).")
        else:
            lots = sorted(r.lots, key=lambda l: abs(l["cost"] - K))
            if lots and K < min(l["cost"] for l in r.lots):
                f.append(f"Strike {K:g} is below your share cost ({min(l['cost'] for l in r.lots):.2f}); if called, you sell at a loss.")
            if K < S:
                f.append(f"This call is already in the money (strike {K:g} below SimQ {S:.2f}).")
    elif act == "buy_to_close":
        if e.get("result", 0) < 0:
            f.append(f"Closing now locks in a loss of {game.money(-e['result'])}.")
    elif act == "sell_shares":
        lots = sorted(r.lots, key=lambda l: l["t"])
        if lots and S < lots[0]["cost"]:
            f.append(f"SimQ {S:.2f} is below your oldest lot's cost ({lots[0]['cost']:.2f}); this sale takes a loss.")
    elif act == "buy_shares":
        if S * int(order.get("qty") or 0) > 0.5 * val:
            f.append("This buys shares worth more than half your account.")
    return f


def api_check(order):
    r = _need()
    chk = r.check(order)
    out = {"ok": chk["ok"], "msg": chk["msg"], "effects": chk.get("effects", {}), "fill": chk.get("fill"),
           "warn": chk.get("warn"), "avail": r.avail, "value": r.value(),
           "flags": _flags(r, order, chk) if chk["ok"] else []}
    q = chk.get("quote")
    if q:
        out["quote"] = {k: q[k] for k in ("bid", "ask", "iv", "delta", "days")}
        if order.get("action") == "sell_to_open":
            out["chances"] = _chances(r, order["type"], float(order["strike"]), q)
            out["ret"] = q["bid"] / float(order["strike"]) if order["type"] == "put" else q["bid"] / r.spot()
            out["ann"] = (1 + out["ret"]) ** (252 / max(q["days"], 1)) - 1
    return out


def _chances(r, typ, K, q):
    S, T, iv = r.spot(), q["days"] / 252, q["iv"]
    if T <= 0 or iv <= 0:
        return None
    rate = float(r.m["rate"][max(r.t - 1, 0)])
    d2 = (math.log(S / K) + (rate - 0.5 * iv * iv) * T) / (iv * math.sqrt(T))
    below = pricing.ncdf(-d2)
    worthless = 1 - below if typ == "put" else below
    prem = q["bid"]
    be = K - prem if typ == "put" else K + prem
    d2b = (math.log(S / be) + (rate - 0.5 * iv * iv) * T) / (iv * math.sqrt(T))
    profit = pricing.ncdf(d2b) if typ == "put" else pricing.ncdf(-d2b)
    return {"worthless": worthless, "assigned": 1 - worthless, "profit": profit, "breakeven": be}


def api_history():
    r = _need()
    return {"events": [_ev(e) for e in reversed(r.events)]}


def _ev(e):
    return {**{k: v for k, v in e.items() if k != "t"}, "t": e["t"], "when": cal.label(e["t"], True)}


def api_indicators(days=260):
    """Daily series up to yesterday's close, plus today's open."""
    r = _need()
    t = r.t
    lo = max(0, t - int(days))
    sl = slice(lo, t)
    m = r.m
    lst = lambda a, n=2: [_f(x, n) for x in a[sl]]  # noqa: E731
    return {"labels": [cal.label(i, True) for i in range(lo, t)], "t0": lo,
            "open": lst(m["open"]), "high": lst(m["high"]), "low": lst(m["low"]), "close": lst(m["close"]),
            "vix": lst(m["vix"]), "fg": lst(m["fg"], 1), "k": lst(m["stoch_k"], 1), "d": lst(m["stoch_d"], 1),
            "iv": [_f(x * 100, 1) for x in m["iv_atm"][sl]],
            "components": {k: lst(v, 0) for k, v in m["fg_components"].items()},
            "today_open": r.spot(), "markers": [{"t": e["t"], "kind": e["kind"], "title": e["title"]}
                                                for e in r.events if e.get("marker") or e["kind"] in ("open", "close")]}


def api_performance():
    r = _need()
    s = r.snaps
    if not s:
        return {"points": [], "stats": None}
    v = np.array([x[1] for x in s])
    peak = np.maximum.accumulate(np.r_[r.cash0, v])[1:]
    dd = float((v / peak - 1).min())
    closed = [e for e in r.events if e["kind"] in ("expired", "close", "assigned", "called")]
    wins = sum(1 for e in closed if e["kind"] == "expired" or (e["kind"] == "close" and e.get("result", 0) >= 0))
    yrs = max(len(s) / 252, 1 / 52)
    stats = {"value": float(v[-1]), "ret": float(v[-1] / r.cash0 - 1), "ann": float((v[-1] / r.cash0) ** (1 / yrs) - 1),
             "max_dd": dd, "bh_ret": float(s[-1][2] / r.cash0 - 1), "cash_ret": float(s[-1][3] / r.cash0 - 1),
             "premium": r.premium, "interest": r.interest_paid,
             "trades": sum(1 for e in r.events if e["kind"] == "open"), "settled": len(closed), "wins": wins,
             "assigned": sum(1 for e in r.events if e["kind"] == "assigned"),
             "called": sum(1 for e in r.events if e["kind"] == "called"), "weeks": len(s) // 5}
    step = max(1, len(s) // 600)
    pts = [{"t": x[0], "label": cal.label(x[0], True), "v": round(x[1], 2), "bh": round(x[2], 2), "cash": round(x[3], 2)}
           for x in s[::step]]
    if pts[-1]["t"] != s[-1][0]:
        x = s[-1]
        pts.append({"t": x[0], "label": cal.label(x[0], True), "v": round(x[1], 2), "bh": round(x[2], 2), "cash": round(x[3], 2)})
    weekly = []
    for w in range(0, len(s) // 5):
        a = s[w * 5 - 1][1] if w else r.cash0
        weekly.append(round(s[w * 5 + 4][1] / a - 1, 4))
    return {"points": pts, "stats": stats, "weekly": weekly,
            "markers": [{"t": e["t"], "kind": e["kind"], "title": e["title"]} for e in r.events if e.get("marker")]}


# ---------------------------------------------------------------- dispatch
METHODS = {n[4:]: f for n, f in globals().items() if n.startswith("api_")}


def dispatch(name, args_json="{}"):
    fn = METHODS.get(name)
    if not fn:
        return 404, json.dumps({"error": f"no such call: {name}"})
    try:
        args = json.loads(args_json or "{}") or {}
        return 200, json.dumps(fn(**args), default=_default)
    except game.TradeError as e:
        return 400, json.dumps({"error": str(e)})
    except TypeError as e:
        return 400, json.dumps({"error": f"bad call: {e}"})
    except Exception as e:  # noqa: BLE001
        import traceback
        traceback.print_exc()
        return 500, json.dumps({"error": f"{type(e).__name__}: {e}"})


def _default(o):
    if isinstance(o, (np.floating, np.integer)):
        return o.item()
    if isinstance(o, np.bool_):
        return bool(o)
    return str(o)

engine/simq/cal.py:
"""Sim calendar: 5 trading days a week, 52 weeks a year, months on a 4-4-5 week pattern. No real dates.

Day t (0-based) -> week t // 5, weekday t % 5 (0 = Monday ... 4 = Friday).
Weekly options expire every Friday; monthlies on the 3rd Friday of each sim month.
"""
DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri")
MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
_MONTH_WEEKS = [4, 4, 5] * 4                       # weeks in each month
_MONTH_START = [sum(_MONTH_WEEKS[:i]) for i in range(12)]


def parts(t):
    w = t // 5
    return {"year": w // 52 + 1, "week": w % 52 + 1, "wday": t % 5, "abs_week": w}


def month_of(t):
    p = parts(t)
    wk = p["week"] - 1
    m = max(i for i in range(12) if _MONTH_START[i] <= wk)
    return p["year"], m


def label(t, short=False):
    p = parts(t)
    y, m = month_of(t)
    if short:
        return f"{DAYS[p['wday']]} W{p['week']} Y{p['year']}"
    return f"{DAYS[p['wday']]}, Week {p['week']} · {MONTHS[m]} · Year {p['year']}"


def friday(t):
    return (t // 5) * 5 + 4


def monthly_fridays(after_t, count):
    """Day index of the 3rd Friday of the next `count` sim months whose expiry is >= after_t."""
    out = []
    y0 = parts(after_t)["year"] - 1
    for y in range(y0, y0 + 3):
        for m in range(12):
            wk = y * 52 + _MONTH_START[m] + 2          # 3rd week of the month
            d = wk * 5 + 4
            if d >= after_t:
                out.append(d)
            if len(out) == count:
                return out
    return out


def expirations(t, weeks=6, months=3):
    """Listed expirations at the open of day t: this Friday (if still ahead) plus the next weeklies,
    and the next monthlies. Returns sorted day indices."""
    f = friday(t)
    weekly = [f + 5 * i for i in range(weeks)]
    monthly = monthly_fridays(t, months)
    return sorted(set(weekly) | set(monthly))


def is_monthly(d):
    return d in monthly_fridays(d, 1) and monthly_fridays(d, 1)[0] == d


def exp_label(d):
    y, m = month_of(d)
    p = parts(d)
    return f"Fri W{p['week']} Y{p['year']}" + (f" · {MONTHS[m]} monthly" if is_monthly(d) else "")

engine/simq/game.py:
"""A SimQ run: the market path for a hidden seed, the book, and every rule.

A run is fully described by (seed, starting cash, actions). Loading replays the actions on the same
path, so saves are tiny and the future can't be read from them.

Clock: the player acts at the OPEN of each trading day. Advancing runs the day to its close (expirations
settle at Friday close, interest accrues daily and is paid at Friday close), then moves to the next open
(splits apply at a Monday open).

Rules (Ghost Trader's): only cash-secured puts and covered calls. A put's full strike x 100 moves from
Available to Collateral; collateral must come from cash already there (not the trade's own premium).
Premium is spendable at once. A call needs 100 free shares per contract. Sells fill at the bid, buys at
the ask. Shares trade at the open price. No fees.
"""
from collections import Counter

import numpy as np

from . import cal, market, pricing

YEAR_DAYS = 252
CHUNK = 5 * 52 * 5          # path generated 5 sim years at a time


class TradeError(Exception):
    pass


def c2(x):
    return round(float(x) + 1e-12, 2)


class Run:
    def __init__(self, seed, cash, actions=(), drift="history"):
        self.seed, self.cash0 = int(seed), float(cash)
        self.drift = drift if drift in market.DRIFTS else "history"
        self.m = None
        self._extend(CHUNK)
        self.t = 0
        self.avail = self.cash0
        self.collateral = 0.0
        self.accrued = 0.0
        self.interest_paid = 0.0
        self.premium = 0.0
        self.positions = {}       # id -> dict
        self.lots = []            # [{id, qty, cost, t, how}]
        self.events = []
        self.snaps = []           # (t, value, bh, cash_bench) at each close
        self.actions = []
        self.next_id = 1
        self.ended = False
        self.bh_shares = self.cash0 / self.m["open"][0]
        self.cash_bench = self.cash0
        self._event("run", f"Run started with {money(self.cash0)}", t=0)
        for a in actions:
            self.apply(a, record=True)

    # ------------------------------------------------------------------ market access
    def _extend(self, n):
        m = market.generate(self.seed, n, 1, drift=self.drift)
        self.m = {k: (v[0] if hasattr(v, "ndim") and v.ndim == 2 else v) for k, v in m.items() if k != "fg_components"}
        self.m["fg_components"] = {k: v[0] for k, v in m["fg_components"].items()}
        k, d = market_stoch(self.m)
        self.m["stoch_k"], self.m["stoch_d"] = k, d
        self.n = n

    def _need(self, t):
        if t + 30 >= self.n:
            self._extend(self.n + CHUNK)

    def spot(self):
        return float(self.m["open"][self.t])

    def _prev(self, key):
        return float(self.m[key][max(self.t - 1, 0)])

    def atm_iv(self, days):
        return float(self.m["iv_open"][self.t]) / pricing.K_WEEK * pricing.iv_mult(days)

    def days_left(self, exp):
        return exp - self.t + 1            # trading days including today (we're at the open)

    def quote(self, typ, K, exp):
        days = self.days_left(exp)
        S = self.spot()
        bid, ask, fair, iv = pricing.quote(S, K, days, self._prev("rate"), self.atm_iv(days), typ == "put",
                                           self._prev("fg"), seed_key=(self.seed, self.t))
        return {"bid": bid, "ask": ask, "mid": round((bid + ask) / 2, 3), "fair": fair, "iv": iv,
                "delta": pricing.delta(S, K, days, self._prev("rate"), iv, typ == "put"), "days": days}

    # ------------------------------------------------------------------ book helpers
    def shares(self):
        return sum(l["qty"] for l in self.lots)

    def covering(self):
        return sum(p["qty"] * 100 for p in self.positions.values() if p["type"] == "call")

    def free_shares(self):
        return self.shares() - self.covering()

    def value(self, price=None):
        price = self.spot() if price is None else price
        return self.avail + self.collateral + self.shares() * price

    def _event(self, kind, title, detail="", t=None, **data):
        self.events.append({"t": self.t if t is None else t, "kind": kind, "title": title, "detail": detail, **data})

    # ------------------------------------------------------------------ actions
    def apply(self, a, record=True):
        if self.ended:
            raise TradeError("This run has ended.")
        kind = a["a"]
        if kind == "order":
            self.place(a, check_only=False)
        elif kind == "advance":
            self.advance(a.get("to", "day"))
        elif kind == "note":
            self._event("note", "Note", a.get("text", ""))
        elif kind == "end":
            self.end()
        else:
            raise TradeError(f"Unknown action {kind}")
        if record:
            self.actions.append(a)

    def check(self, o):
        """Validate an order and work out its effects. Returns dict(ok, msg, effects, fill)."""
        act, qty = o.get("action"), int(o.get("qty") or 0)
        res = {"ok": False, "msg": "", "effects": {}, "order": o}
        if qty <= 0:
            res["msg"] = "Enter how many " + ("shares." if "shares" in act else "contracts.")
            return res
        S = self.spot()
        if act in ("buy_shares", "sell_shares"):
            cost = S * qty
            if act == "buy_shares":
                if cost > self.avail + 1e-9:
                    res["msg"] = f"Not enough available cash: {money(cost)} needed, {money(self.avail)} available."
                    return res
                res["effects"] = {"cash": -cost, "shares": qty}
            else:
                if qty > self.free_shares():
                    res["msg"] = f"Only {self.free_shares()} shares are free (the rest cover calls)."
                    return res
                res["effects"] = {"cash": cost, "shares": -qty}
            res.update(ok=True, fill=round(S, 2))
            return res
        if act == "sell_to_open":
            typ, K, exp = o["type"], float(o["strike"]), int(o["expiry"])
            if exp not in cal.expirations(self.t):
                res["msg"] = "That expiration isn't listed today."
                return res
            q = self.quote(typ, K, exp)
            if q["bid"] <= 0:
                res["msg"] = "No bid on this contract."
                return res
            prem = q["bid"] * 100 * qty
            if typ == "put":
                coll = K * 100 * qty
                if coll > self.avail + 1e-9:
                    res["msg"] = (f"Not cash-secured: {money(coll)} collateral needed, {money(self.avail)} available "
                                  "(premium can't fund its own collateral).")
                    return res
                res["effects"] = {"premium": prem, "collateral": coll, "avail_after": self.avail - coll + prem}
            else:
                if qty * 100 > self.free_shares():
                    res["msg"] = f"Not covered: {self.free_shares()} free shares, {qty * 100} needed."
                    return res
                res["effects"] = {"premium": prem, "locks": qty * 100, "avail_after": self.avail + prem}
            res.update(ok=True, fill=q["bid"], quote=q)
            if typ == "put" and res["effects"]["collateral"] > 0.8 * self.value():
                res["warn"] = "This trade's collateral is more than 80% of your account value."
            return res
        if act == "buy_to_close":
            p = self.positions.get(int(o["position_id"]))
            if not p:
                res["msg"] = "No such open position."
                return res
            if qty > p["qty"]:
                res["msg"] = f"You hold {p['qty']} contracts."
                return res
            q = self.quote(p["type"], p["strike"], p["expiry"])
            cost = q["ask"] * 100 * qty
            rel = p["collateral"] * qty / p["qty"] if p["type"] == "put" else 0.0
            if cost > self.avail + rel + 1e-9:
                res["msg"] = f"Not enough cash to buy back: {money(cost)} needed."
                return res
            res["effects"] = {"cost": cost, "released": rel, "result": (p["open_px"] - q["ask"]) * 100 * qty,
                              "avail_after": self.avail + rel - cost}
            res.update(ok=True, fill=q["ask"], quote=q)
            return res
        res["msg"] = "Unknown order."
        return res

    def place(self, o, check_only=False):
        chk = self.check(o)
        if not chk["ok"]:
            raise TradeError(chk["msg"])
        if check_only:
            return chk
        act, qty, px = o["action"], int(o["qty"]), chk["fill"]
        S = self.spot()
        note, tags = o.get("note", ""), o.get("tags", [])
        if act == "buy_shares":
            self.avail -= px * qty
            self.lots.append({"id": self._id(), "qty": qty, "cost": px, "t": self.t, "how": "bought"})
            self._event("shares", f"Bought {qty} SimQ @ {px:.2f}", money(-px * qty), note=note, tags=tags)
        elif act == "sell_shares":
            self._remove_shares(qty, px, "sold")
            self.avail += px * qty
            self._event("shares", f"Sold {qty} SimQ @ {px:.2f}", money(px * qty), note=note, tags=tags)
        elif act == "sell_to_open":
            typ, K, exp = o["type"], float(o["strike"]), int(o["expiry"])
            prem = px * 100 * qty
            pid = self._id()
            coll = K * 100 * qty if typ == "put" else 0.0
            self.avail += prem - coll
            self.collateral += coll
            self.premium += prem
            self.positions[pid] = {"id": pid, "type": typ, "strike": K, "expiry": exp, "qty": qty,
                                   "open_px": px, "open_t": self.t, "collateral": coll, "spot_at_open": S,
                                   "note": note, "tags": tags, "label": contract_label(typ, K, exp)}
            self._event("open", f"Sell to open {qty} × {contract_label(typ, K, exp)} @ {px:.2f}",
                        f"premium {money(prem)}" + (f" · collateral {money(coll)}" if coll else " · covered"),
                        pid=pid, note=note, tags=tags)
        elif act == "buy_to_close":
            p = self.positions[int(o["position_id"])]
            cost = px * 100 * qty
            rel = p["collateral"] * qty / p["qty"] if p["type"] == "put" else 0.0
            self.collateral -= rel
            self.avail += rel - cost
            self.premium -= cost
            res = (p["open_px"] - px) * 100 * qty
            p["collateral"] -= rel
            p["qty"] -= qty
            self._event("close", f"Buy to close {qty} × {p['label']} @ {px:.2f}",
                        f"{money(-cost)} · result {money(res, True)}", pid=p["id"], result=res, note=o.get("note", ""))
            if p["qty"] == 0:
                del self.positions[p["id"]]
        return chk

    def _id(self):
        self.next_id += 1
        return self.next_id - 1

    def _remove_shares(self, qty, px, how):
        left = qty
        for l in sorted(self.lots, key=lambda x: x["t"]):
            take = min(left, l["qty"])
            l["qty"] -= take
            left -= take
            if left == 0:
                break
        self.lots = [l for l in self.lots if l["qty"] > 0]

    # ------------------------------------------------------------------ the clock
    def target(self, to="day"):
        """day: the next open. friday: Friday's open (or next Friday's if today is Friday). week: next Monday's open."""
        if to == "day":
            return self.t + 1
        if to == "friday":
            return cal.friday(self.t) if self.t % 5 != 4 else self.t + 5
        if to == "week":
            return cal.friday(self.t) + 1
        raise TradeError("Unknown advance")

    def advance(self, to="day"):
        target = self.target(to)
        while self.t < target:
            self._close_day()
            self.t += 1
            self._need(self.t)
            self._open_day()

    def _close_day(self):
        t = self.t
        close = float(self.m["close"][t])
        rate = float(self.m["rate"][t])
        days_passed = 3 if t % 5 == 4 else 1     # Friday close accrues the weekend
        self.accrued += (self.avail + self.collateral) * rate * days_passed / 365.0
        for p in [p for p in self.positions.values() if p["expiry"] == t]:
            self._settle(p, close)
        if t % 5 == 4:
            if self.accrued > 0:
                self.avail += self.accrued
                self.interest_paid += self.accrued
                self._event("interest", f"Interest paid {money(self.accrued, True)}", f"rate {rate * 100:.2f}%")
                self.accrued = 0.0
        if self.m["meeting"][t]:
            d = int(self.m["decision"][t])
            word = {0: "holds", 1: "hikes 0.25", 2: "hikes 0.50", -1: "cuts 0.25", -2: "cuts 0.50"}[d]
            self._event("rate", f"Central bank {word}: rate now {rate * 100:.2f}%", "")
        self.cash_bench *= 1 + rate * days_passed / 365.0
        self.snaps.append((t, self.value(close) + 0.0, self.bh_shares * close, self.cash_bench))

    def _settle(self, p, close):
        K, q = p["strike"], p["qty"]
        if p["type"] == "put":
            if close <= K - 0.01:
                self.collateral -= p["collateral"]
                self.lots.append({"id": self._id(), "qty": 100 * q, "cost": K, "t": self.t, "how": "assigned"})
                self._event("assigned", f"Put assigned: bought {100 * q} SimQ @ {K:.2f}",
                            f"{p['label']} · SimQ closed {close:.2f}", pid=p["id"], marker=True)
            else:
                self.collateral -= p["collateral"]
                self.avail += p["collateral"]
                self._event("expired", f"Expired worthless: {p['label']}", f"SimQ closed {close:.2f} · kept {money(p['open_px'] * 100 * q)}", pid=p["id"])
        else:
            if close >= K + 0.01:
                self._remove_shares(100 * q, K, "called")
                self.avail += K * 100 * q
                self._event("called", f"Called away: sold {100 * q} SimQ @ {K:.2f}",
                            f"{p['label']} · SimQ closed {close:.2f}", pid=p["id"], marker=True)
            else:
                self._event("expired", f"Expired worthless: {p['label']}", f"SimQ closed {close:.2f} · kept {money(p['open_px'] * 100 * q)}", pid=p["id"])
        del self.positions[p["id"]]

    def _open_day(self):
        t = self.t
        if self.m["split"][t]:
            r = float(self.m["split_ratio"][t])        # price multiplied by r
            if r > 1:   # reverse split: options can't be adjusted cleanly, so they're closed at fair value first
                for p in list(self.positions.values()):
                    fv = pricing.fair(float(self.m["close"][t - 1]), p["strike"], self.days_left(p["expiry"]), self._prev("rate"),
                                      self.atm_iv(self.days_left(p["expiry"])), p["type"] == "put")[0]
                    cost = fv * 100 * p["qty"]
                    self.collateral -= p["collateral"]
                    self.avail += p["collateral"] - cost
                    self._event("close", f"Closed for the split: {p['label']} @ {fv:.2f}", money(-cost), pid=p["id"])
                    del self.positions[p["id"]]
                old = self.shares()
                for l in self.lots:
                    l["qty"], l["cost"] = l["qty"] / r, l["cost"] * r
                whole = sum(int(l["qty"]) for l in self.lots)
                frac = old / r - whole
                for l in self.lots:
                    l["qty"] = int(l["qty"])
                self.lots = [l for l in self.lots if l["qty"] > 0]
                self.avail += frac * float(self.m["open"][t])
                self._event("split", f"1-for-{r:g} reverse split", f"{old} shares → {whole}; fractions paid in cash", marker=True)
            else:
                f = 1.0 / r
                for l in self.lots:
                    l["qty"], l["cost"] = int(round(l["qty"] * f)), l["cost"] / f
                for p in self.positions.values():
                    p["strike"], p["qty"], p["open_px"] = p["strike"] / f, int(p["qty"] * f), p["open_px"] / f
                    p["label"] = contract_label(p["type"], p["strike"], p["expiry"])
                self.bh_shares *= f
                self._event("split", f"{f:g}-for-1 split", "shares and option contracts multiplied; strikes divided", marker=True)
            if r > 1:
                self.bh_shares /= r

    def end(self):
        self.ended = True
        self._event("end", "Run ended", f"seed {self.seed}")

    # ------------------------------------------------------------------ views
    def eras(self):
        """Which real years this run's market came from (shown only after the run ends)."""
        days = market.history()["days"]
        src = self.m["src"][: self.t + 1].astype(int)
        c = Counter(days[i][:4] for i in src)
        n = sum(c.values())
        return sorted(((y, k / n) for y, k in c.items()), key=lambda x: -x[1])


def market_stoch(m, k=14, d=3):
    h, l, c = m["high"], m["low"], m["close"]
    T = len(c)
    K = np.full(T, np.nan)
    for t in range(k - 1, T):
        hh, ll = h[t - k + 1:t + 1].max(), l[t - k + 1:t + 1].min()
        K[t] = 100.0 * (c[t] - ll) / max(hh - ll, 1e-12)
    D = np.full(T, np.nan)
    for t in range(k + d - 2, T):
        D[t] = K[t - d + 1:t + 1].mean()
    return K, D


def contract_label(typ, K, exp):
    return f"{cal.exp_label(exp).split(' · ')[0]} ${K:g} {'Put' if typ == 'put' else 'Call'}"


def money(x, sign=False):
    s = "−" if x < 0 else ("+" if sign and x > 0 else "")
    return f"{s}${abs(x):,.2f}"

