"""Option pricing: SimQ v2's model (Black-Scholes, steep put skew, short-expiry steepening, price floor,
spreads by price / moneyness / fear, light messy quotes), with the IV level from the real VXN (v3).

Same formulas and parameters as simq-sim v2 (ruleset v2.0 "pricing"); scipy replaced with an erf-based
normal CDF so it runs in the browser.
"""
import hashlib
import math

YEAR_DAYS = 252.0
PP = {
    "skew_slope_range": [1.3, 1.6], "skew_iv_range": [0.82, 1.01], "skew_short_exp": 0.33,
    "skew_clamp": [0.55, 1.6], "floor_value": 0.02, "zero_below": 0.002,
    "spread_base": 0.01, "spread_per_dollar": 0.05, "spread_itm_mult": 3.0,
    "spread_deep_itm_per_pct": 0.08, "spread_deep_itm_cap_pct": 10.0, "spread_fear_mult": 0.6,
    "messy_half_strike_frac": 0.1, "messy_mult": [3.0, 5.0],
}
# ATM IV = k x VXN; k falls from 2.9 for weeklies (real Oct 23 / Nov 6 2026 chains) to 2.65 for ~1 month (published IV30)
K_WEEK, K_MONTH = 2.9, 2.65


def ncdf(x):
    return 0.5 * math.erfc(-x / math.sqrt(2.0))


def iv_mult(days):
    """IV/VXN ratio for an option with `days` trading days left."""
    if days <= 5:
        return K_WEEK
    if days >= 21:
        return K_MONTH
    return K_WEEK + (K_MONTH - K_WEEK) * (days - 5) / 16.0


def bs(S, K, T, r, iv, put):
    T = max(T, 1e-9)
    sq = iv * math.sqrt(T)
    d1 = (math.log(S / K) + (r + 0.5 * iv * iv) * T) / sq
    d2 = d1 - sq
    call = S * ncdf(d1) - K * math.exp(-r * T) * ncdf(d2)
    return call - S + K * math.exp(-r * T) if put else call


def delta(S, K, days, r, iv, put):
    T = max(days / YEAR_DAYS, 1e-9)
    d1 = (math.log(S / K) + (r + 0.5 * iv * iv) * T) / (iv * math.sqrt(T))
    return ncdf(d1) - 1.0 if put else ncdf(d1)


def strike_iv(spot, K, atm_iv, days, pp=PP):
    lo_iv, hi_iv = pp["skew_iv_range"]
    lo_sl, hi_sl = pp["skew_slope_range"]
    w = min(max((atm_iv - lo_iv) / (hi_iv - lo_iv), 0.0), 1.0)
    slope = (lo_sl + (hi_sl - lo_sl) * w) * (5.0 / min(max(days, 0.25), 5.0)) ** pp["skew_short_exp"]
    lo, hi = pp["skew_clamp"]
    return atm_iv * min(max(1.0 - slope * (K / spot - 1.0), lo), hi)


def fair(spot, K, days, rate, atm_iv, put, pp=PP):
    iv = strike_iv(spot, K, atm_iv, days, pp)
    return bs(spot, K, days / YEAR_DAYS, rate, iv, put), iv


def list_strikes(spot):
    """$1 steps (plus .5 strikes within 10%), $0.50 under $15, $2.50 over $150; 40%-160% of spot."""
    if spot < 15:
        step, half = 0.5, None
    elif spot < 150:
        step, half = 1.0, 0.10
    else:
        step, half = 2.5, None
    ks = set()
    k = math.floor(spot * 0.40 / step) * step
    while k <= spot * 1.60 + 1e-9:
        if k > 0:
            ks.add(round(k, 2))
        k += step
    if half:
        k = math.floor(spot * (1 - half)) + 0.5
        while k < spot * (1 + half):
            ks.add(round(k, 2))
            k += 1.0
    return sorted(ks)


def _messy(seed_key, K, frac):
    h = hashlib.sha256(f"{seed_key}|{K:.2f}".encode()).digest()
    return int.from_bytes(h[:8], "big") / 2 ** 64 < frac, int.from_bytes(h[8:16], "big") / 2 ** 64


def quote(spot, K, days, rate, atm_iv, put, fg_score, seed_key=None, pp=PP):
    """(bid, ask, fair, iv). bid 0.0 = no bid."""
    f, iv = fair(spot, K, days, rate, atm_iv, put, pp)
    if f < pp["zero_below"]:
        return 0.0, 0.01, f, iv
    mid = max(f, pp["floor_value"])
    width = pp["spread_base"] + pp["spread_per_dollar"] * mid
    itm = (K > spot) if put else (K < spot)
    if itm:
        depth = abs(K / spot - 1.0) * 100.0
        width *= pp["spread_itm_mult"] * (1.0 + pp["spread_deep_itm_per_pct"] * min(depth, pp["spread_deep_itm_cap_pct"]))
    width *= 1.0 + pp["spread_fear_mult"] * max(0.0, (25.0 - fg_score) / 25.0)
    if seed_key is not None and abs(K - round(K)) > 0.25:
        hit, y = _messy(seed_key, K, pp["messy_half_strike_frac"])
        if hit:
            lo, hi = pp["messy_mult"]
            width *= lo + (hi - lo) * y
    bid = max(math.floor((mid - width / 2.0) * 100.0) / 100.0, 0.01)
    ask = max(math.ceil((mid + width / 2.0) * 100.0) / 100.0, bid + 0.01)
    return round(bid, 2), round(ask, 2), f, iv
